jetons = lambda t: re.findall(r"\*\*|\s+|\w+|[^\w\s]", t)
BORD = " \t\n,.;:!?)(«»\"'-–—"      # ponctuation et espaces laissés hors du surlignage

def surligner(morceaux):
  # Entoure de == chaque suite de mots ajoutés ; ponctuation en bordure et ** restent dehors
  sortie, groupe = [], []
  def fermer():
    if groupe:
      texte = "".join(groupe)
      coeur = texte.strip(BORD)
      if coeur:
        i = texte.index(coeur)
        sortie.append(texte[:i] + "==" + coeur + "==" + texte[i + len(coeur):])
      else:
        sortie.append(texte)
      del groupe[:]
  for j in morceaux:
    if j == "**":
      fermer()
      sortie.append(j)
    else:
      groupe.append(j)
  fermer()
  return "".join(sortie)

